    required this.signDeg,
    required this.nakshatraDeg,
    required this.padaDeg,
    required this.length,
  });

  /// Which graha.
  final Uint16List graha;

  /// The sign it stands in.
  final Uint16List sign;

  /// The bhava it falls in, under the chart's placement system.
  final Uint8List house;

  /// Its dignity.
  final Uint16List dignity;

  /// How it stands to its dispositor by the table's own reading.
  final Uint16List natural;

  /// How it stands to its dispositor by where that body stands.
  final Uint16List temporary;

  /// The five-fold compound of the two.
  final Uint16List compound;

  /// 1 when the sign has a lord; 0 only for a body the catalogue gives no sign.
  final Uint8List hasDispositor;

  /// The lord of the sign, which all three relationships are with.
  final Uint16List dispositor;

  /// What the Sun does to it.
  final Uint8List burning;

  /// 1 when the chart carries a Sun to measure from; 0 when it does not, in which case nothing is burnt and this says why rather than claiming the sky is clear.
  final Uint8List hasFromSun;

  /// How far from the Sun it stands, degrees; read only when `has_from_sun`.
  final Float64List fromSunDeg;

  /// 1 when the table gives this body an orb; 0 for a body that does not burn at all.
  final Uint8List hasOrbs;

  /// Combust inside this, degrees; read only when `has_orbs`.
  final Float64List orbDeg;

  /// 1 when the table gives a deeper orb as well.
  final Uint8List hasDeepOrb;

  /// Deeply combust inside this, degrees; read only when `has_deep_orb`.
  final Float64List deepOrbDeg;

  /// Which fifth of its sign it stands in.
  final Uint16List age;

  /// Awake, dreaming or asleep.
  final Uint16List wakefulness;

  /// 1 when the SDK can decide a bright state.
  final Uint8List hasDeeptadi;

  /// The bright state; read only when `has_deeptadi`.
  final Uint16List deeptadi;

  /// The lajjitadi that hold, as a bit set: bit `n` is the member with catalogue id `n`.
  final Uint32List lajjitadiHolding;

  /// The lajjitadi that certainly do not hold, because the tradition's own necessary condition fails, as a bit set.
  final Uint32List lajjitadiRuledOut;

  /// The lajjitadi nothing decides: the necessary condition holds and what narrows it further is not in the chart. A bit set, so a caller can tell a short list from an empty one.
  final Uint32List lajjitadiUndecided;

  /// 1 when the body is in a planetary war.
  final Uint8List hasWar;

  /// The other body; read only when `has_war`.
  final Uint16List warOpponent;

  /// 1 when this body won it; read only when `has_war`.
  final Uint8List warWon;

  /// How far apart they stand, degrees; read only when `has_war`.
  final Float64List warApartDeg;

  /// How near it stands to a sign edge, degrees.
  final Float64List signDeg;

  /// How near it stands to a nakshatra edge, degrees.
  final Float64List nakshatraDeg;

  /// How near it stands to a pada edge, degrees.
  final Float64List padaDeg;

  /// The number of rows every column holds.
  final int length;
}

/// The `dashas` section of a Charts blob: one typed list per column, each a
/// view over the blob's bytes rather than a copy.
///
/// Every chart's dashas, charts outermost and then the systems in the order asked: row `i * dasha_count + j` is chart `i`'s `j`th. Each row's periods are the next `period_count` rows of `dasha_periods`, in the same order. Empty when no dashas were asked for.
final class ChartsDashas {
  const ChartsDashas({
    required this.system,
    required this.seed,
    required this.firstLord,
    required this.overflow,
    required this.balance,
    required this.remaining,
    required this.balanceDays,
    required this.balanceYears,
    required this.balanceMonths,
    required this.balanceDayCount,
    required this.balanceHours,
    required this.balanceMinutes,
    required this.moonSpanFrom,
    required this.moonSpanTo,
    required this.depth,
    required this.periodCount,
    required this.length,
  });

  /// Which system.
  final Uint16List system;

  /// The nakshatra the Moon stood in, which seeds it.
  final Uint16List seed;

  /// The lord it starts with.
  final Uint16List firstLord;

  /// 1 when the seed lay outside a conditional system's nakshatras and started at the first lord because the settings let it.
  final Uint8List overflow;

  /// How the balance was measured.
  final Uint8List balance;

  /// The fraction of the first lord's period still to run at birth, 0 to 1.
  final Float64List remaining;

  /// That fraction of the first lord's years, in days.
  final Float64List balanceDays;

  /// The balance's whole years of the year length.
  final Uint32List balanceYears;

  /// Its whole months of a twelfth of the year length.
  final Uint8List balanceMonths;

  /// Its whole days.
  final Uint8List balanceDayCount;

  /// Its hours, the rest rounded to the minute.
  final Uint8List balanceHours;

  /// Its minutes, rounded.
  final Uint8List balanceMinutes;

  /// When the Moon entered its nakshatra, a Julian day (UTC); NaN when the balance was spatial and read no span.
  final Float64List moonSpanFrom;

  /// When it left, a Julian day (UTC); NaN when no span was read.
  final Float64List moonSpanTo;

  /// How many levels the periods go down, 1 to 6.
  final Uint8List depth;

  /// How many rows of `dasha_periods` are this dasha's.
  final Uint32List periodCount;

  /// The number of rows every column holds.
  final int length;
}

/// The `dasha_periods` section of a Charts blob: one typed list per column, each a
/// view over the blob's bytes rather than a copy.
///
/// Every dasha's periods of its birth cycle, concatenated in the `dashas` section's order and **ragged** by its `period_count`, each dasha's depth first in time order: a mahadasha, then its antardashas and theirs, then the next mahadasha. A period's path is its `index` below the nearest earlier period one `level` up.
final class ChartsDashaPeriods {
  const ChartsDashaPeriods({
    required this.level,
    required this.index,
    required this.lord,
    required this.fromJd,
    required this.toJd,
    required this.length,
  });

  /// How deep: 1 for a mahadasha.
  final Uint8List level;

  /// Its place in its parent's sequence, from 0; under the elapsed reading of the birth period the first may not be 0.
  final Uint8List index;

  /// Its lord.
  final Uint16List lord;

  /// When it begins, a Julian day (UTC).
  final Float64List fromJd;

  /// When it ends, a Julian day (UTC).
  final Float64List toJd;

  /// The number of rows every column holds.
  final int length;
}

/// The `day` section, wherever a blob carries it: one typed list per column, each a
/// view over the blob's bytes rather than a copy.
///
/// The day each instant belongs to: its arc, its date and how it was reckoned. One row per row of the blob's own grid.
final class Day {
  const Day({
    required this.sunrise,
    required this.sunset,
    required this.nextSunrise,
    required this.vara,
    required this.calendar,
    required this.era,
    required this.year,
    required this.eraYear,
    required this.month,
    required this.dayOfMonth,
    required this.resolution,
    required this.computedMonth,
    required this.computedDay,
    required this.stateKind,
    required this.statePolarKind,
    required this.statePolarPolicy,
    required this.conventionKind,
    required this.conventionValue,
    required this.length,
  });

  /// The sunrise that opened the day, as a Julian day (UTC).
  final Float64List sunrise;

  /// The sunset that closed its daylight, as a Julian day (UTC).
  final Float64List sunset;

  /// The sunrise that closes it, as a Julian day (UTC).
  final Float64List nextSunrise;

  /// The weekday the day carries.
  final Uint16List vara;

  /// The calendar the date is in.
  final Uint16List calendar;

  /// The era the date's year is counted in.
  final Uint16List era;

  /// The astronomical year; 1 BCE is 0.
  final Int32List year;

  /// The year as the era counts it.
  final Int32List eraYear;

  /// The month, 1 to 12 or 13.
  final Uint8List month;

  /// The day of the month.
  final Uint8List dayOfMonth;

  /// How the date was resolved.
  final Uint8List resolution;

  /// The engine's month where it differs from the table's; zero otherwise.
  final Uint8List computedMonth;

  /// The engine's day where it differs from the table's; zero otherwise.
  final Uint8List computedDay;

  /// Whether the day had a sunrise at all.
  final Uint8List stateKind;

  /// Which polar state it was, when it had none; zero otherwise.
  final Uint8List statePolarKind;

  /// Which policy synthesised its bounds, when it had none; zero otherwise.
  final Uint8List statePolarPolicy;

  /// Which sunrise convention the arc was reckoned by; `0xFF` for a custom altitude.
  final Uint8List conventionKind;

  /// The altitude in degrees when the convention is custom; zero otherwise.
  final Float64List conventionValue;

  /// The number of rows every column holds.
  final int length;
}

/// A decoded Charts blob.
///
/// A batch of founded charts at one place: the grahas placed, the bhavas under both readings, the zodiac, the day and the timing. Every per-chart section runs charts outermost, and a batch of one is the ordinary case.
final class Charts {
  const Charts({
    required this.kind,
    required this.chartCount,
    required this.grahaCount,
    required this.vargaCount,
    required this.dashaCount,
    required this.latitudeDeg,
    required this.longitudeDeg,
    required this.altitudeM,
    required this.cast,
    required this.grahas,
    required this.housesMethod,
    required this.housesSource,
    required this.housesReading,
    required this.chalitMethod,
    required this.chalitSource,
    required this.chalitReading,
    required this.houses,
    required this.chalit,
    required this.frameBits,
    required this.ayanamshaKind,
    required this.ayanamsha,
    required this.day,
    required this.timing,
    required this.model,
    required this.steps,
    required this.provenance,
    required this.vargas,
    required this.vargaGrahas,
    required this.aspects,
    required this.drishtiTable,
    required this.points,
    required this.bhavas,
    required this.states,
    required this.combustionOrbs,
    required this.drawings,
    required this.svgs,
    required this.dashas,
    required this.dashaPeriods,
  });

  /// What kind of chart these are.
  final int kind;

  /// How many charts the batch holds, and how many rows the `cast`, `day` and `timing` sections each hold.
  final int chartCount;

  /// How many grahas each chart holds; the `grahas` section holds `chart_count * graha_count` rows.
  final int grahaCount;

  /// How many divisional charts were asked for, in the order asked; zero when none were. The `vargas` section holds `chart_count * varga_count` rows and `varga_grahas` holds `chart_count * varga_count * graha_count`.
  final int vargaCount;

  /// How many dashas were asked for, in the order asked; zero when none were. The `dashas` section holds `chart_count * dasha_count` rows.
  final int dashaCount;

  /// The place's latitude, degrees north.
  final double latitudeDeg;

  /// The place's longitude, degrees east.
  final double longitudeDeg;

  /// The place's altitude, metres.
  final double altitudeM;

  /// One row per chart, in the order the instants were asked for.
  final ChartsCast cast;

  /// One row per graha per chart, charts outermost: row `i * graha_count + j` is chart `i`, graha `j`, grahas in the catalogue's order. `house_*` is the bhava for "which house is it in"; `placement_*` is the chart's chalit, which is a different question and often a different answer.
  final ChartsGrahas grahas;

  /// The system the houses were computed under.
  final int housesMethod;

  /// The system its cusps came from.
  final int housesSource;

  /// Which bound the houses are read against.
  final int housesReading;

  /// The system the chalit was computed under.
  final int chalitMethod;

  /// The system its cusps came from.
  final int chalitSource;

  /// Which bound the chalit is read against.
  final int chalitReading;

  /// The twelve bhavas for "which house is it in", charts outermost: row `i * 12 + j` is chart `i`, bhava `j`, first to twelfth.
  final ChartsHouses houses;

  /// The twelve bhavas of each chart's chalit, the same shape as `houses`.
  final ChartsChalit chalit;

  /// The frame the positions were asked for, packed as the port packs it.
  final int frameBits;

  /// 0 for none, 1 for a catalogued ayanamsha, 2 for one the settings define.
  final int ayanamshaKind;

  /// Which catalogued ayanamsha, when the kind is 1.
  final int ayanamsha;

  /// The day each instant belongs to: its arc, its date and how it was reckoned. One row per row of the blob's own grid.
  final Day day;

  /// Where in its day each moment falls, in the reckonings the settings named: one row per chart.
  final ChartsTiming timing;

  /// UTF-8 text: the solar model that reckoned the days, as it describes itself.
  final String model;

  /// UTF-8 JSON: an array of strings, the completion steps applied in order, each `name:Implementation`. The positions blob carries the same steps as objects and spells the implementation differently (`PASS_THROUGH` against `PassThrough`); which of the two every blob should use is an open question (`03-design/chart-at-the-boundary.md` §8).
  final String steps;

  /// UTF-8 JSON: the provenance envelope of the result, canonical.
  final String provenance;

  /// One row per divisional chart per chart, charts outermost: row `i * varga_count + v` is chart `i`, the `v`th chart asked for. Empty when none were asked for, which is unambiguous because a divisional chart that *was* asked for always has a lagna (`03-design/chart-reading.md` §5).
  final ChartsVargas vargas;

  /// One row per graha per divisional chart per chart, charts outermost then charts asked for: row `(i * varga_count + v) * graha_count + j` is chart `i`, the `v`th divisional chart, graha `j` in the `grahas` section's own order. Empty when no divisional chart was asked for.
  final ChartsVargaGrahas vargaGrahas;

  /// Every chart's drishti, concatenated charts outermost and **ragged**: chart `i`'s rows begin at the sum of every earlier chart's `cast.aspect_count` and run for its own, ordered by the looking body and then by the body looked at, in the foundation's own order. Empty when the aspects were not asked for. `from_*` and `to_*` say how near each end stands to a boundary, which is what an ayanamsha that moved would change.
  final ChartsAspects aspects;

  /// UTF-8 text: the drishti table the settings named, which every aspect above was read under. Empty when the aspects were not asked for.
  final String drishtiTable;

  /// Every chart's derived points — the upagrahas and the special lagnas — concatenated charts outermost and **ragged**: chart `i`'s rows begin at the sum of every earlier chart's `cast.point_count` and run for its own. Empty when the points were not asked for. Gulika and Mandi are Saturn's eighth of the day's arc and are the two a chart with no arc to divide cannot have.
  final ChartsPoints points;

  /// Twelve rows per chart, charts outermost: row `i * 12 + j` is chart `i`, bhava `j + 1`. Empty when the houses were not asked for, which is unambiguous because a chart that has bhavas has twelve. The madhya and the sandhi are in `houses` and `chalit`; this is what only the houses service computes.
  final ChartsBhavas bhavas;

  /// One row per graha per chart, charts outermost: row `i * graha_count + j` is chart `i`, graha `j`, in the `grahas` section's own order. Empty when the states were not asked for, which is unambiguous because a chart that has states has one per graha.
  ///
  /// The **motion** is not here: `grahas.speed_deg_per_day` already carries it and retrograde is its sign, and describing a shape twice is what `03-design/chart-at-the-boundary.md` §3 exists to prevent.
  final ChartsStates states;

  /// UTF-8 text: the combustion table the settings named, which every `burning` above was judged against. Empty when the states were not asked for.
  final String combustionOrbs;

  /// UTF-8 JSON, canonical: an array with one entry per chart, each the array of that chart's drawings in the order asked for, every drawing `{varga, placed}` exactly as the document schema describes `Drawing` (`03-design/chart-geometry.md`). Empty when no drawings were asked for.
  final String drawings;

  /// UTF-8 JSON, canonical: an array with one entry per chart, each the array of that chart's drawings written as SVG strings, in the order asked for, in the request's theme and the context's locale (`03-design/render-svg.md`). Empty when no theme was given.
  final String svgs;

  /// Every chart's dashas, charts outermost and then the systems in the order asked: row `i * dasha_count + j` is chart `i`'s `j`th. Each row's periods are the next `period_count` rows of `dasha_periods`, in the same order. Empty when no dashas were asked for.
  final ChartsDashas dashas;

  /// Every dasha's periods of its birth cycle, concatenated in the `dashas` section's order and **ragged** by its `period_count`, each dasha's depth first in time order: a mahadasha, then its antardashas and theirs, then the next mahadasha. A period's path is its `index` below the nearest earlier period one `level` up.
  final ChartsDashaPeriods dashaPeriods;

}

/// Decodes a Charts blob. The columns are views over `bytes`, so the
/// buffer must outlive the result; a blob of another layout version or
/// another schema is a [FormatException].
Charts decodeCharts(Uint8List bytes) {
  final blob = _Blob.open(bytes, 3, 'charts');
  final atSummary = blob.section(1, 'summary');
  final atCast = blob.section(2, 'cast');
  final atGrahas = blob.section(3, 'grahas');
  final atReadings = blob.section(4, 'readings');
  final atHouses = blob.section(5, 'houses');
  final atChalit = blob.section(6, 'chalit');
  final atZodiac = blob.section(7, 'zodiac');
  final atDay = blob.section(8, 'day');
  final atTiming = blob.section(9, 'timing');
  final atModel = blob.section(10, 'model');
  final atSteps = blob.section(11, 'steps');
  final atProvenance = blob.section(12, 'provenance');
  final atVargas = blob.section(13, 'vargas');
  final atVargaGrahas = blob.section(14, 'varga_grahas');
  final atAspects = blob.section(15, 'aspects');
  final atDrishtiTable = blob.section(16, 'drishti_table');
  final atPoints = blob.section(17, 'points');
  final atBhavas = blob.section(18, 'bhavas');
  final atStates = blob.section(19, 'states');
  final atCombustionOrbs = blob.section(20, 'combustion_orbs');
  final atDrawings = blob.section(21, 'drawings');
  final atSvgs = blob.section(22, 'svgs');
  final atDashas = blob.section(23, 'dashas');
  final atDashaPeriods = blob.section(24, 'dasha_periods');
  return Charts(
    kind: blob.data.getUint16(atSummary.offset + 0, Endian.little),
    chartCount: blob.data.getUint32(atSummary.offset + 8, Endian.little),
    grahaCount: blob.data.getUint32(atSummary.offset + 16, Endian.little),
    vargaCount: blob.data.getUint32(atSummary.offset + 24, Endian.little),
    dashaCount: blob.data.getUint32(atSummary.offset + 32, Endian.little),
    latitudeDeg: blob.data.getFloat64(atSummary.offset + 40, Endian.little),
    longitudeDeg: blob.data.getFloat64(atSummary.offset + 48, Endian.little),
    altitudeM: blob.data.getFloat64(atSummary.offset + 56, Endian.little),
    cast: ChartsCast(
      instant: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 0),
        blob.columnOffset(atCast, 0) + atCast.count * 8,
      ),
      lagnaDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 1),
        blob.columnOffset(atCast, 1) + atCast.count * 8,
      ),
      dayLagnaDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 2),
        blob.columnOffset(atCast, 2) + atCast.count * 8,
      ),
      ayanamshaOffsetDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 3),
        blob.columnOffset(atCast, 3) + atCast.count * 8,
      ),
      dayPart: Uint8List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 4),
        blob.columnOffset(atCast, 4) + atCast.count * 1,
      ),
      dayElapsed: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 5),
        blob.columnOffset(atCast, 5) + atCast.count * 8,
      ),
      pointCount: Uint32List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 6),
        blob.columnOffset(atCast, 6) + atCast.count * 4,
      ),
      aspectCount: Uint32List.sublistView(
        blob.bytes,
        blob.columnOffset(atCast, 7),
        blob.columnOffset(atCast, 7) + atCast.count * 4,
      ),
      length: atCast.count,
    ),
    grahas: ChartsGrahas(
      graha: Uint16List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 0),
        blob.columnOffset(atGrahas, 0) + atGrahas.count * 2,
      ),
      longitudeDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 1),
        blob.columnOffset(atGrahas, 1) + atGrahas.count * 8,
      ),
      tropicalDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 2),
        blob.columnOffset(atGrahas, 2) + atGrahas.count * 8,
      ),
      latitudeDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 3),
        blob.columnOffset(atGrahas, 3) + atGrahas.count * 8,
      ),
      distanceAu: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 4),
        blob.columnOffset(atGrahas, 4) + atGrahas.count * 8,
      ),
      speedDegPerDay: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 5),
        blob.columnOffset(atGrahas, 5) + atGrahas.count * 8,
      ),
      houseBhava: Uint8List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 6),
        blob.columnOffset(atGrahas, 6) + atGrahas.count * 1,
      ),
      houseMethod: Uint16List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 7),
        blob.columnOffset(atGrahas, 7) + atGrahas.count * 2,
      ),
      houseThrough: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 8),
        blob.columnOffset(atGrahas, 8) + atGrahas.count * 8,
      ),
      houseFromMadhyaDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 9),
        blob.columnOffset(atGrahas, 9) + atGrahas.count * 8,
      ),
      placementBhava: Uint8List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 10),
        blob.columnOffset(atGrahas, 10) + atGrahas.count * 1,
      ),
      placementMethod: Uint16List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 11),
        blob.columnOffset(atGrahas, 11) + atGrahas.count * 2,
      ),
      placementThrough: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 12),
        blob.columnOffset(atGrahas, 12) + atGrahas.count * 8,
      ),
      placementFromMadhyaDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atGrahas, 13),
        blob.columnOffset(atGrahas, 13) + atGrahas.count * 8,
      ),
      length: atGrahas.count,
    ),
    housesMethod: blob.data.getUint16(atReadings.offset + 0, Endian.little),
    housesSource: blob.data.getUint16(atReadings.offset + 8, Endian.little),
    housesReading: blob.data.getUint8(atReadings.offset + 16),
    chalitMethod: blob.data.getUint16(atReadings.offset + 24, Endian.little),
    chalitSource: blob.data.getUint16(atReadings.offset + 32, Endian.little),
    chalitReading: blob.data.getUint8(atReadings.offset + 40),
    houses: ChartsHouses(
      madhyaDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atHouses, 0),
        blob.columnOffset(atHouses, 0) + atHouses.count * 8,
      ),
      sandhiDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atHouses, 1),
        blob.columnOffset(atHouses, 1) + atHouses.count * 8,
      ),
      length: atHouses.count,
    ),
    chalit: ChartsChalit(
      madhyaDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atChalit, 0),
        blob.columnOffset(atChalit, 0) + atChalit.count * 8,
      ),
      sandhiDeg: Float64List.sublistView(
        blob.bytes,
        blob.columnOffset(atChalit, 1),
        blob.columnOffset(atChalit, 1) + atChalit.count * 8,
      ),
      length: atChalit.count,
    ),
    frameBits: blob.data.getUint32(atZodiac.offset + 0, Endian.little),
    ayanamshaKind: blob.data.getUint8(atZodiac.offset + 8),
    ayanamsha: blob.data.getUint16(atZodiac.offset + 16, Endian.little),
    day: Day(
      sunrise: Float64List.sublistView(
