      moonSigns: Uint32List.sublistView(
        blob.bytes,
        blob.columnOffset(atCounts, 5),
        blob.columnOffset(atCounts, 5) + atCounts.count * 4,
      ),
      sunSigns: Uint32List.sublistView(
